    solution="import sys\nfrom collections import deque\ninput = sys.stdin.readline\nr, c = map(int, input().split())\ng = [bytearray(input().rstrip(), 'ascii') for _ in range(r)]\nLAND = ord('#')\ncount = best = 0\nfor i in range(r):\n    row = g[i]\n    for j in range(c):\n        if row[j] != LAND:\n            continue\n        count += 1\n        row[j] = 0\n        q = deque([(i, j)])\n        size = 0\n        while q:\n            x, y = q.popleft()\n            size += 1\n            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):\n                if 0 <= nx < r and 0 <= ny < c and g[nx][ny] == LAND:\n                    g[nx][ny] = 0\n                    q.append((nx, ny))\n        best = max(best, size)\nprint(count, best)",
