    examples=[("4 4\n####\n#JF#\n#..#\n#..#", "3"), ("3 3\n###\n#J#\n###", "IMPOSSIBLE")],
    hidden=["1 1\nJ", "3 3\n...\n.J.\n..F", "3 5\n#####\n#J.F.\n#####",
            G("r = c = 700\nprint(r, c)\ng = [['#' if random.random() < 0.25 else '.' for _ in range(c)] for _ in range(r)]\ng[350][350] = 'J'\nfor _ in range(30):\n    g[random.randrange(r)][random.randrange(c)] = 'F'\ng[350][350] = 'J'\nprint('\\n'.join(''.join(x) for x in g))", 126),
            G("r = c = 700\nprint(r, c)\ng = [['.'] * c for _ in range(r)]\ng[0][0] = 'J'\ng[r - 1][c - 1] = 'F'\nprint('\\n'.join(''.join(x) for x in g))", 127)],
    hint="① 모든 불에서 동시에 시작하는 BFS로 칸마다 불이 도착하는 시각 fire[x][y]를 구합니다(다중 시작점 BFS). ② 사람의 BFS에서 시각 t+1에 칸 (x, y)로 가려면 t+1 < fire[x][y]여야 합니다.",
    solution="import sys\nfrom collections import deque\ninput = sys.stdin.readline\nr, c = map(int, input().split())\ng = [input().rstrip() for _ in range(r)]\nINF = 1 << 30\nfire = [[INF] * c for _ in range(r)]\nq = deque()\nfor i in range(r):\n    for j in range(c):\n        if g[i][j] == 'F':\n            fire[i][j] = 0\n            q.append((i, j))\n        elif g[i][j] == 'J':\n            start = (i, j)\nwhile q:\n    x, y = q.popleft()\n    t = fire[x][y] + 1\n    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):\n        if 0 <= nx < r and 0 <= ny < c and fire[nx][ny] == INF and g[nx][ny] != '#':\n            fire[nx][ny] = t\n            q.append((nx, ny))\ndist = [[-1] * c for _ in range(r)]\nsx, sy = start\ndist[sx][sy] = 0\nq = deque([start])\nanswer = 'IMPOSSIBLE'\nwhile q:\n    x, y = q.popleft()\n    t = dist[x][y] + 1\n    if x == 0 or y == 0 or x == r - 1 or y == c - 1:\n        answer = t\n        break\n    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):\n        if dist[nx][ny] < 0 and g[nx][ny] == '.' and t < fire[nx][ny]:\n            dist[nx][ny] = t\n            q.append((nx, ny))\nprint(answer)",
    brute="r, c = map(int, input().split())\ng = [list(input()) for _ in range(r)]\nfire = {(i, j) for i in range(r) for j in range(c) if g[i][j] == 'F'}\npeople = {(i, j) for i in range(r) for j in range(c) if g[i][j] == 'J'}\nseen = set(people)\nt = 0\nanswer = 'IMPOSSIBLE'\nwhile people:\n    t += 1\n    if any(i in (0, r - 1) or j in (0, c - 1) for i, j in people):\n        answer = t\n        break\n    nf = set(fire)\n    for i, j in fire:\n        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):\n            if 0 <= a < r and 0 <= b < c and g[a][b] != '#':\n                nf.add((a, b))\n    fire = nf\n    npeople = set()\n    for i, j in people:\n        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):\n            if 0 <= a < r and 0 <= b < c and g[a][b] == '.' and (a, b) not in fire and (a, b) not in seen:\n                npeople.add((a, b))\n    seen |= npeople\n    people = npeople\nprint(answer)",
