    solution="import sys\nfrom bisect import bisect_left\ninput = sys.stdin.readline\nn = int(input())\ntails = []\nfor x in map(int, input().split()):\n    i = bisect_left(tails, x)\n    if i == len(tails):\n        tails.append(x)\n    else:\n        tails[i] = x\nprint(len(tails))",
