    solution="import sys\ninput = sys.stdin.readline\nn, W = map(int, input().split())\nbest = [0] * (W + 1)\nfor _ in range(n):\n    wi, vi = map(int, input().split())\n    if wi > W:\n        continue\n    shifted = [b + vi for b in best[:W + 1 - wi]]\n    best[wi:] = map(max, best[wi:], shifted)\nprint(best[W])",
